import{_ as d,o as r,c as o,ag as e}from"./chunks/framework.D2veAa-g.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-面向对象-设计模式","description":"","frontmatter":{"title":"架构师-备考 综合知识-面向对象-设计模式"},"headers":[],"relativePath":"综合知识/面向对象/设计模式.md","filePath":"综合知识/面向对象/设计模式.md","lastUpdated":null}'),a={name:"综合知识/面向对象/设计模式.md"};function n(s,t,l,h,i,g){return r(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 设计模式层次（架构模式/设计模式/惯用法）</li><li>[x] 创建型模式（单例/工厂方法/抽象工厂/建造者/原型）</li><li>[x] 结构型模式（适配器/桥接/组合/装饰/外观/享元/代理）</li><li>[x] 行为型模式（观察者/策略/模板方法/命令/状态/责任链/迭代器/中介者/备忘录/解释器/访问者）</li><li>[x] 桥接模式详解</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、设计模式层次" tabindex="-1">一、设计模式层次 <a class="header-anchor" href="#一、设计模式层次" aria-label="Permalink to &quot;一、设计模式层次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>说明</th><th style="text-align:center;">粒度</th></tr></thead><tbody><tr><td><strong>架构模式</strong></td><td>软件系统整体结构，高层模式</td><td style="text-align:center;">大</td></tr><tr><td><strong>设计模式</strong></td><td>子系统或组件的设计方案</td><td style="text-align:center;">中</td></tr><tr><td><strong>惯用法</strong></td><td>特定语言相关的编程技巧</td><td style="text-align:center;">小</td></tr></tbody></table><hr><h3 id="二、三大类设计模式总览-★" tabindex="-1">二、三大类设计模式总览 ★ <a class="header-anchor" href="#二、三大类设计模式总览-★" aria-label="Permalink to &quot;二、三大类设计模式总览 ★&quot;">​</a></h3><h4 id="创建型模式-5种" tabindex="-1">创建型模式（5种） <a class="header-anchor" href="#创建型模式-5种" aria-label="Permalink to &quot;创建型模式（5种）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>核心思想</th><th>一句话</th></tr></thead><tbody><tr><td><strong>单例（Singleton）</strong></td><td>一个类仅有一个实例，提供全局访问点</td><td>唯一实例</td></tr><tr><td><strong>工厂方法（Factory Method）</strong></td><td>定义创建对象的接口，子类决定实例化哪个类</td><td>子类决定创建什么</td></tr><tr><td><strong>抽象工厂（Abstract Factory）</strong></td><td>创建一系列相关对象，无需指定具体类</td><td>产品族</td></tr><tr><td><strong>建造者（Builder）</strong></td><td>复杂对象的构建与表示分离</td><td>分步构造</td></tr><tr><td><strong>原型（Prototype）</strong></td><td>通过复制现有对象创建新对象</td><td>克隆</td></tr></tbody></table><blockquote><p>口诀：<strong>单原建，工抽分。</strong>（单例/原型/建造者/工厂方法/抽象工厂）</p></blockquote><h4 id="结构型模式-7种" tabindex="-1">结构型模式（7种） <a class="header-anchor" href="#结构型模式-7种" aria-label="Permalink to &quot;结构型模式（7种）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>核心思想</th><th>一句话</th></tr></thead><tbody><tr><td><strong>适配器（Adapter）</strong></td><td>将接口转换为客户期望的另一个接口</td><td>接口转换</td></tr><tr><td><strong>桥接（Bridge）</strong></td><td>抽象与实现分离，独立变化</td><td>多维变化分离</td></tr><tr><td><strong>组合（Composite）</strong></td><td>将对象组成树形结构，统一处理单个对象和组合</td><td>部分-整体</td></tr><tr><td><strong>装饰（Decorator）</strong></td><td>动态给对象添加额外职责</td><td>包装增强</td></tr><tr><td><strong>外观（Facade）</strong></td><td>为子系统中的一组接口提供统一入口</td><td>简化接口</td></tr><tr><td><strong>享元（Flyweight）</strong></td><td>共享大量细粒度对象，减少内存占用</td><td>共享复用</td></tr><tr><td><strong>代理（Proxy）</strong></td><td>为其他对象提供代理以控制访问</td><td>控制访问</td></tr></tbody></table><blockquote><p>口诀：<strong>适桥组装外享代。</strong></p></blockquote><h4 id="行为型模式-11种" tabindex="-1">行为型模式（11种） <a class="header-anchor" href="#行为型模式-11种" aria-label="Permalink to &quot;行为型模式（11种）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>核心思想</th><th>一句话</th></tr></thead><tbody><tr><td><strong>观察者（Observer）</strong></td><td>一对多依赖，一对象状态变化通知所有依赖者</td><td>发布-订阅</td></tr><tr><td><strong>策略（Strategy）</strong></td><td>定义一系列算法，可相互替换</td><td>算法族</td></tr><tr><td><strong>模板方法（Template Method）</strong></td><td>定义算法骨架，子类重定义某些步骤</td><td>骨架不变子类填空</td></tr><tr><td><strong>命令（Command）</strong></td><td>将请求封装为对象，支持撤销/排队</td><td>请求封装</td></tr><tr><td><strong>状态（State）</strong></td><td>对象行为随内部状态改变</td><td>状态决定行为</td></tr><tr><td><strong>责任链（Chain of Responsibility）</strong></td><td>多个对象处理同一请求，形成链条</td><td>传递处理</td></tr><tr><td><strong>迭代器（Iterator）</strong></td><td>顺序访问集合元素而不暴露内部表示</td><td>遍历</td></tr><tr><td><strong>中介者（Mediator）</strong></td><td>用中介对象封装一系列对象交互</td><td>中心协调</td></tr><tr><td><strong>备忘录（Memento）</strong></td><td>捕获对象内部状态，支持撤销</td><td>快照/回滚</td></tr><tr><td><strong>解释器（Interpreter）</strong></td><td>定义语言文法并解释执行</td><td>语法解释</td></tr><tr><td><strong>访问者（Visitor）</strong></td><td>在不改变元素类的前提下定义新操作</td><td>操作分离</td></tr></tbody></table><blockquote><p>口诀：<strong>观策模命状，责迭中备解访。</strong></p></blockquote><hr><h3 id="三、桥接模式详解-★" tabindex="-1">三、桥接模式详解 ★ <a class="header-anchor" href="#三、桥接模式详解-★" aria-label="Permalink to &quot;三、桥接模式详解 ★&quot;">​</a></h3><blockquote><p>桥接模式将<strong>抽象部分与它的实现部分分离</strong>，使它们可以独立变化。是比多重继承更好的解决方法（多重继承违背单一职责原则）。</p></blockquote><p><strong>四个角色：</strong></p><table tabindex="0"><thead><tr><th>角色</th><th>作用</th></tr></thead><tbody><tr><td><strong>Abstraction</strong>（抽象类）</td><td>定义抽象类接口，维护 Implementor 指针</td></tr><tr><td><strong>RefinedAbstraction</strong>（扩充抽象类）</td><td>扩充由 Abstraction 定义的接口</td></tr><tr><td><strong>Implementor</strong>（实现类接口）</td><td>定义实现类接口，提供基本操作（可与 Abstraction 完全不同）</td></tr><tr><td><strong>ConcreteImplementor</strong>（具体实现类）</td><td>实现 Implementor 接口的具体实现</td></tr></tbody></table><blockquote><p>Abstraction 定义高层操作（基于基本操作），Implementor 仅提供基本操作。二者接口可以完全不同，独立变化。</p></blockquote>',22)])])}const p=d(a,[["render",n]]);export{c as __pageData,p as default};
